import { KPI_GROUPS } from 'pages/constants';

import {
  KPIS_MEASURE_MAP,
  KPIS_TITLE_MAP,
  LINEBAR_CHART_COLORS,
} from '../constants';

export const getCommercialResultsConfig = ({
  kpiSlug,
}: {
  kpiSlug: string;
}) => {
  return {
    kpiGroup: KPI_GROUPS[kpiSlug],
    periodValues: ['YTD', 'L3M', 'MTD'],
    measure: KPIS_MEASURE_MAP[kpiSlug],
    driversTitle: `${KPIS_TITLE_MAP[kpiSlug]} Drivers`,
  };
};

export const getColor = (label?: string): string => {
  if (label === 'Last Year') return LINEBAR_CHART_COLORS.lastYear;
  if (label === 'Budget') return LINEBAR_CHART_COLORS.budget;
  return LINEBAR_CHART_COLORS.current;
};

export const getBarColors = (labels: string[], stripedIndexes: number[]) => {
  return labels.map((_, index, array) => {
    if (stripedIndexes.includes(index)) {
      return LINEBAR_CHART_COLORS.budget;
    }

    if (index === array.length - 1) {
      return LINEBAR_CHART_COLORS.current;
    }

    return LINEBAR_CHART_COLORS.lastYear;
  });
};
